CREATE TABLE IF NOT EXISTS "se_pdf_annotation_layout" (id INTEGER PRIMARY KEY CHECK (id = 1), binding TEXT NOT NULL);
INSERT INTO "se_pdf_annotation_layout" (id, binding) VALUES (1, '{"collections":[{"collection":"annotations","columns":[{"indexed":false,"name":"color","type":"TEXT"},{"indexed":false,"name":"comment","type":"TEXT"},{"indexed":false,"name":"created_at","type":"TEXT"},{"indexed":false,"name":"document_id","type":"TEXT"},{"indexed":false,"name":"id","type":"TEXT"},{"indexed":false,"name":"page_index","type":"REAL"},{"indexed":false,"name":"position","type":"TEXT"},{"indexed":false,"name":"text","type":"TEXT"},{"indexed":false,"name":"updated_at","type":"TEXT"}],"table":"se_pdf_annotation_annotations"},{"collection":"documents","columns":[{"indexed":false,"name":"created_at","type":"TEXT"},{"indexed":false,"name":"file_name","type":"TEXT"},{"indexed":false,"name":"id","type":"TEXT"},{"indexed":false,"name":"number_of_annotations","type":"REAL"},{"indexed":false,"name":"source_key","type":"TEXT"},{"indexed":false,"name":"source_type","type":"TEXT"},{"indexed":false,"name":"source_url","type":"TEXT"},{"indexed":false,"name":"title","type":"TEXT"},{"indexed":false,"name":"updated_at","type":"TEXT"}],"table":"se_pdf_annotation_documents"},{"collection":"highlight_colors","columns":[{"indexed":false,"name":"color","type":"TEXT"},{"indexed":false,"name":"semantics","type":"TEXT"}],"table":"se_pdf_annotation_highlight_colors"}],"format":"d1-records/v1","prefix":"se_pdf_annotation_","schema":"{\"collections\":[{\"indexes\":[\"byDocument\",\"byDocumentPage\"],\"name\":\"annotations\"},{\"indexes\":[\"bySource\"],\"name\":\"documents\"},{\"indexes\":[],\"name\":\"highlight_colors\"}],\"version\":\"pdf-annotation/1\"}"}') ON CONFLICT (id) DO UPDATE SET binding = CASE WHEN binding = excluded.binding THEN binding ELSE NULL END;
CREATE TABLE IF NOT EXISTS "se_pdf_annotation_streams" (stream_id TEXT PRIMARY KEY, revision INTEGER NOT NULL CHECK (revision >= 0), contract_version TEXT NOT NULL, schema_binding TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "se_pdf_annotation_guards" (id INTEGER PRIMARY KEY CHECK (id = 1), valid INTEGER NOT NULL CHECK (valid = 1));
CREATE TABLE IF NOT EXISTS "se_pdf_annotation_meta" (stream_id TEXT NOT NULL, sort_key TEXT COLLATE BINARY NOT NULL, key_json TEXT NOT NULL, value_json TEXT NOT NULL, PRIMARY KEY (stream_id, sort_key));
CREATE TABLE IF NOT EXISTS "se_pdf_annotation_canonical" (stream_id TEXT NOT NULL, sort_key TEXT COLLATE BINARY NOT NULL, key_json TEXT NOT NULL, value_json TEXT NOT NULL, PRIMARY KEY (stream_id, sort_key));
CREATE TABLE IF NOT EXISTS "se_pdf_annotation_identities" (stream_id TEXT NOT NULL, sort_key TEXT COLLATE BINARY NOT NULL, key_json TEXT NOT NULL, value_json TEXT NOT NULL, PRIMARY KEY (stream_id, sort_key));
CREATE TABLE IF NOT EXISTS "se_pdf_annotation_positions" (stream_id TEXT NOT NULL, sort_key TEXT COLLATE BINARY NOT NULL, key_json TEXT NOT NULL, value_json TEXT NOT NULL, PRIMARY KEY (stream_id, sort_key));
CREATE TABLE IF NOT EXISTS "se_pdf_annotation_decisions" (stream_id TEXT NOT NULL, sort_key TEXT COLLATE BINARY NOT NULL, key_json TEXT NOT NULL, value_json TEXT NOT NULL, PRIMARY KEY (stream_id, sort_key));
CREATE TABLE IF NOT EXISTS "se_pdf_annotation_accepted" (stream_id TEXT NOT NULL, sort_key TEXT COLLATE BINARY NOT NULL, key_json TEXT NOT NULL, value_json TEXT NOT NULL, PRIMARY KEY (stream_id, sort_key));
CREATE TABLE IF NOT EXISTS "se_pdf_annotation_annotations" (__sync_stream TEXT NOT NULL, __sync_key TEXT COLLATE BINARY NOT NULL, __sync_data TEXT NOT NULL, "__sync_index_0" TEXT COLLATE BINARY, "__sync_index_1" TEXT COLLATE BINARY, "color" TEXT, "comment" TEXT, "created_at" TEXT, "document_id" TEXT, "id" TEXT, "page_index" REAL, "position" TEXT, "text" TEXT, "updated_at" TEXT, PRIMARY KEY (__sync_stream, __sync_key));
CREATE INDEX IF NOT EXISTS "se_pdf_annotation_annotations_sync_i0" ON "se_pdf_annotation_annotations" (__sync_stream, "__sync_index_0", __sync_key);
CREATE INDEX IF NOT EXISTS "se_pdf_annotation_annotations_sync_i1" ON "se_pdf_annotation_annotations" (__sync_stream, "__sync_index_1", __sync_key);
CREATE TABLE IF NOT EXISTS "se_pdf_annotation_documents" (__sync_stream TEXT NOT NULL, __sync_key TEXT COLLATE BINARY NOT NULL, __sync_data TEXT NOT NULL, "__sync_index_0" TEXT COLLATE BINARY, "created_at" TEXT, "file_name" TEXT, "id" TEXT, "number_of_annotations" REAL, "source_key" TEXT, "source_type" TEXT, "source_url" TEXT, "title" TEXT, "updated_at" TEXT, PRIMARY KEY (__sync_stream, __sync_key));
CREATE INDEX IF NOT EXISTS "se_pdf_annotation_documents_sync_i0" ON "se_pdf_annotation_documents" (__sync_stream, "__sync_index_0", __sync_key);
CREATE TABLE IF NOT EXISTS "se_pdf_annotation_highlight_colors" (__sync_stream TEXT NOT NULL, __sync_key TEXT COLLATE BINARY NOT NULL, __sync_data TEXT NOT NULL, "color" TEXT, "semantics" TEXT, PRIMARY KEY (__sync_stream, __sync_key));
